INSERT INTO public.gastronomy (id, department_id, dish_name, category, origin_history, ancestral_technique, status, hidden_gem) VALUES
('gastro_madriz_1', 'madriz', 'Rosquillas de Somoto y Yalagüina', 'plato_fuerte', 'Elaboradas artesanalmente con maíz blanco seleccionado, queso seco criollo, cuajada fresca y mantequilla de hacienda, doradas a leña en hornos de barro.', 'Elaboración tradicional artesanal', 'published', false),
('gastro_madriz_2', 'madriz', 'Viejitas y Hojaldras', 'plato_fuerte', 'Bocados crujientes de masa de maíz con dulce de panela (rapadura) derretida en su centro.', 'Elaboración tradicional artesanal', 'published', false),
('gastro_madriz_3', 'madriz', 'Montucas Madricenses', 'plato_fuerte', 'Tamal tierno de elote condimentado con pollo de patio, hierbabuena, leche y un toque sutil de chile congo.', 'Elaboración tradicional artesanal', 'published', false),
('gastro_madriz_4', 'madriz', 'Café de Estricta Altura', 'plato_fuerte', 'Variedades Caturra, Borbón y Catuaí cultivadas bajo sombra de montaña en San Juan del Río Coco entre 1,000 y 1,400 msnm.', 'Elaboración tradicional artesanal', 'published', false),
('gastro_madriz_5', 'madriz', 'Gorditas de Maíz y Güirilas', 'plato_fuerte', 'Tortas dulces asadas en hojas de plátano acompañadas con cuajada fresca de hacienda.', 'Elaboración tradicional artesanal', 'published', false),
('gastro_madriz_6', 'madriz', 'Rosquillas en Miel de Caña', 'plato_fuerte', 'Postre tradicional de Semana Santa y fiestas patronales bañado en almíbar de dulce de atado.', 'Elaboración tradicional artesanal', 'published', false),
('gastro_leon_1', 'leon', 'Ruta del Quesillo', 'plato_fuerte', 'Nagarote y La Paz Centro comparten esta tradición de tortilla, queso, crema y cebolla encurtida.', 'Elaboración tradicional artesanal', 'published', false),
('gastro_leon_2', 'leon', 'Cocina Tradicional', 'plato_fuerte', 'Vigorón, nacatamal, indio viejo, chancho con yuca, carne asada y tamales.', 'Elaboración tradicional artesanal', 'published', false),
('gastro_leon_3', 'leon', 'Sopas y Maíz', 'plato_fuerte', 'Sopa de res, sopa de queso, güirilas y tortillas preparadas con saberes familiares.', 'Elaboración tradicional artesanal', 'published', false),
('gastro_leon_4', 'leon', 'Lácteos y Dulces', 'plato_fuerte', 'Quesos, cajetas, rosquillas y otros dulces tradicionales de occidente.', 'Elaboración tradicional artesanal', 'published', false),
('gastro_leon_5', 'leon', 'Bebidas de Identidad', 'plato_fuerte', 'Cacao, pinolillo, tiste, chicha y distintas bebidas tradicionales de maíz.', 'Elaboración tradicional artesanal', 'published', false),
('gastro_leon_6', 'leon', 'Sabores del Centro Histórico', 'plato_fuerte', 'Mercados, dulcerías, cafés y emprendimientos familiares con cocina local.', 'Elaboración tradicional artesanal', 'published', false),
('gastro_rivas_1', 'rivas', 'Pescado del Cocibolca', 'plato_fuerte', 'Pescado fresco preparado por familias y cocinas vinculadas con la vida lacustre.', 'Elaboración tradicional artesanal', 'published', false),
('gastro_rivas_2', 'rivas', 'Mariscos del Pacífico', 'plato_fuerte', 'Productos del mar servidos en San Juan del Sur, Tola y comunidades pesqueras.', 'Elaboración tradicional artesanal', 'published', false),
('gastro_rivas_3', 'rivas', 'Productos de Plátano', 'plato_fuerte', 'Tostones, tajadas y otras preparaciones fundamentales de la cocina rivense.', 'Elaboración tradicional artesanal', 'published', false),
('gastro_rivas_4', 'rivas', 'Sopas y Nacatamales', 'plato_fuerte', 'Recetas tradicionales acompañadas con tortillas y productos locales.', 'Elaboración tradicional artesanal', 'published', false),
('gastro_rivas_5', 'rivas', 'Sabores de Ometepe', 'plato_fuerte', 'Plátano, frutas, miel, café, pescado y cocina campesina de las fincas de la isla.', 'Elaboración tradicional artesanal', 'published', false),
('gastro_rivas_6', 'rivas', 'Cacao y Bebidas Tradicionales', 'plato_fuerte', 'Bebidas y productos tropicales elaborados en comunidades y emprendimientos.', 'Elaboración tradicional artesanal', 'published', false),
('gastro_jinotega_1', 'jinotega', 'Café SHG de Estricta Altura', 'plato_fuerte', 'Notas de chocolate, jazmín y frutas cítricas cosechado a más de 1,400 msnm.', 'Elaboración tradicional artesanal', 'published', false),
('gastro_jinotega_2', 'jinotega', 'Güirilas con Cuajada Fresca', 'plato_fuerte', 'Tortilla dulce de maíz tierno asada en hoja de plátano.', 'Elaboración tradicional artesanal', 'published', false),
('gastro_jinotega_3', 'jinotega', 'Agua de Loja Jinotegana', 'plato_fuerte', 'Bebida a base de maíz hervido con jengibre y dulce de rapadura.', 'Elaboración tradicional artesanal', 'published', false),
('gastro_jinotega_4', 'jinotega', 'Sopa de Gallina India con Albóndigas', 'plato_fuerte', 'Cocida con leña en fogones campesinos.', 'Elaboración tradicional artesanal', 'published', false),
('gastro_jinotega_5', 'jinotega', 'Panadería de Yalí', 'plato_fuerte', 'Rosquillas, perrerreque, quesadillas, semitas, dulces y bebidas tradicionales de maíz.', 'Elaboración tradicional artesanal', 'published', false),
('gastro_jinotega_6', 'jinotega', 'Productos de Finca', 'plato_fuerte', 'Cacao, miel, cuajada, queso, crema, frijoles, tamales y sopa de cuajada.', 'Elaboración tradicional artesanal', 'published', false),
('gastro_masaya_1', 'masaya', 'Sopa de Mondongo', 'plato_fuerte', 'Uno de los sabores más característicos del departamento y de su cocina festiva.', 'Elaboración tradicional artesanal', 'published', false),
('gastro_masaya_2', 'masaya', 'Tamuga de Monimbó', 'plato_fuerte', 'Preparación tradicional estrechamente vinculada con la identidad comunitaria de Monimbó.', 'Elaboración tradicional artesanal', 'published', false),
