('gastro_masaya_4', 'masaya', 'Vigorón y Yuca', 'plato_fuerte', 'Preparaciones populares presentes en mercados, barrios y celebraciones.', 'Elaboración tradicional artesanal', 'published', false),
('gastro_masaya_5', 'masaya', 'Dulces y Cajetas', 'plato_fuerte', 'Dulces tradicionales elaborados por familias y emprendimientos locales.', 'Elaboración tradicional artesanal', 'published', false),
