INSERT INTO public.historical_figures (id, department_id, full_name, role_title, birth_year, death_year, biography, legacy_summary, status) VALUES
('fig_ruben_dario', 'matagalpa', 'Rubén Darío (Félix Rubén García Sarmiento)', 'Príncipe de las Letras Castellanas y Padre del Modernismo', 1867, 1916, 'Nacido en Ciudad Darío (antiguo Chocoyos), revolucionó el idioma castellano en todo el mundo hispánico con Azul... y Prosas Profanas.', 'Renovador universal de la métrica poética y embajador inmortal de la dignidad nicaragüense.', 'published'),
('fig_augusto_sandino', 'masaya', 'General Augusto C. Sandino', 'Héroe Nacional y Defensor de la Soberanía', 1895, 1934, 'Nacido en Niquinohomo, lideró en Las Segovias el Ejército Defensor de la Soberanía Nacional contra la intervención armada extranjera.', 'Símbolo perenne de soberanía popular, justicia territorial campesina y dignidad latinoamericana.', 'published'),
('fig_jose_dolores_estrada', 'managua', 'General José Dolores Estrada Vado', 'Héroe de la Batalla de San Jacinto', 1792, 1869, 'Nacido en Nandaime, dirigió con arrojo y estrategia patriótica la victoria nicaragüense en la Hacienda San Jacinto el 14 de septiembre de 1856.', 'Defensa irreductible de la independencia patria contra el filibusterismo esclavista.', 'published'),
('fig_camilo_zapata', 'managua', 'Camilo Zapata', 'Creador del Son Nica', 1917, 2009, 'Pionero de la música típica nicaragüense al crear en compás 6/8 el ritmo autóctono Son Nica con el Caballito Chingo.', 'Fundador de la identidad musical popular y folclórica nicaragüense.', 'published'),
('fig_justo_santos', 'rivas', 'Justo Santos Cerda', 'Compositor del Himno Popular La Mora Limpia', 1931, 1958, 'Músico y guitarrista virtuoso creador de La Mora Limpia, considerada unánimemente el segundo himno de Nicaragua.', 'Creador del tema sonoro más identitario y conmovedor del folclore nacional.', 'published')
