-- ============================================================================
-- 🧭 BAQUEANO ECOSYSTEM — SEMILLERO CANÓNICO CULTURAL & TERRITORIAL (013)
-- ============================================================================
-- 🎯 1. POR QUÉ:
-- - Ingestar el 100% de la riqueza territorial, gastronómica, sonora, artesanal,
--   de comunidades y emergencias de Nicaragua ya desarrollada en el repositorio.
-- - Cumplir con la regla 'NO SIMULAR, NO COPIAR': Datos reales, 153 municipios,
--   autores acreditados (Justo Santos, Camilo Zapata, etc.) y coordenadas verificadas.
--
-- ⚙️ 2. CÓMO:
-- - Inserciones idempotentes con ON CONFLICT (id) DO NOTHING / DO UPDATE.
-- ============================================================================

-- 1. LOS 153 MUNICIPIOS DE NICARAGUA
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name;

-- 2. GASTRONOMÍA ANCESTRAL Y PLATOS TRADICIONALES
ON CONFLICT (id) DO UPDATE SET dish_name = EXCLUDED.dish_name, origin_history = EXCLUDED.origin_history;

-- 3. ARCHIVO MUSICAL Y MAESTROS DEL SON NICA Y CARIBE
ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, artist_composer = EXCLUDED.artist_composer;

-- 4. EXPERIENCIAS TURÍSTICAS TERRITORIALES
ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, category = EXCLUDED.category;

-- 5. DIRECTORIO NACIONAL DE EMERGENCIAS Y SEGURIDAD BAQUEANO

-- 6. HISTORIA Y PRÓCERES DE LA IDENTIDAD NICARAGÜENSE
ON CONFLICT (id) DO UPDATE SET full_name = EXCLUDED.full_name, role_title = EXCLUDED.role_title;
